-- Disposable project only. Run after the policy migration inside BEGIN/ROLLBACK.
begin;
create function pg_temp.test_payment_adjustments() returns jsonb language plpgsql as $$
declare u uuid; actor uuid; s uuid:=gen_random_uuid(); lot uuid; op text; plan text; r jsonb; evidence jsonb; blocked boolean; results jsonb:='[]';
begin
 select id into u from public.profiles where status='active' and role='client' limit 1;
 select id into actor from public.profiles where status='active' and role in ('admin','staff') limit 1;
 select plan_key into plan from public.ai_agent_subscription_plans where active limit 1;
 select operation_key into op from public.ai_credit_operations where active limit 1;
 perform set_config('request.jwt.claims','{"role":"service_role"}',true);
 insert into public.ai_agent_subscriptions(id,user_id,plan_key,billing_interval,status,currency,amount) values(s,u,plan,'monthly','active','USD',10);
 insert into public.ai_subscription_payments(reference,subscription_id,provider_transaction_id,amount_minor,currency,paid_at,period_start,period_end) values('refund-rollback-fixture',s,'refund-rollback-tx',1000,'USD',now(),now(),now()+interval '1 month');
 select id into lot from public.ai_payment_credit_lots where payment_reference='refund-rollback-fixture' and period_start=date_trunc('month',now());
 insert into public.ai_credit_ledger(user_id,subscription_id,plan_key,period_start,period_end,operation_key,credits,status,idempotency_key,payment_credit_lot_id) values(u,s,plan,date_trunc('month',now()),date_trunc('month',now())+interval '1 month',op,2,'consumed','refund-rollback-fixture-usage',lot);
 evidence:=jsonb_build_object('action','refund','provider_object_id','refund:rollbackfixture1','reference','refund-rollback-fixture','transaction_id','refund-rollback-tx','currency','USD','amount_minor',300,'verification_source','provider_api');
 blocked:=false;begin perform public.apply_ai_payment_adjustment(actor,'Verified fixture provider evidence',evidence);exception when others then blocked:=true;end;
 if not blocked then raise exception 'Disabled gate allowed adjustment'; end if;
 results:=results||'[{"name":"disabled policy gate","status":"pass"}]';
 update public.ai_refund_policy_config set enabled=true where id;
 r:=public.apply_ai_payment_adjustment(actor,'Verified fixture provider evidence',evidence);
 if r->>'administrator_review'<>'true' or (select revoked or frozen from public.ai_payment_credit_lots where id=lot) then raise exception 'Partial refund altered benefits'; end if;
 r:=public.apply_ai_payment_adjustment(actor,'Verified fixture provider evidence',evidence);
 if r->>'duplicate'<>'true' or (select count(*) from public.ai_payment_adjustments where payment_reference='refund-rollback-fixture')<>1 then raise exception 'Duplicate adjustment'; end if;
 results:=results||'[{"name":"partial refund preserves benefits and duplicate is idempotent","status":"pass"}]';
 evidence:=evidence||'{"action":"dispute_open","provider_object_id":"dispute:rollbackfixture1","amount_minor":1000}';
 insert into public.ai_credit_ledger(user_id,subscription_id,plan_key,period_start,period_end,operation_key,credits,status,idempotency_key,payment_credit_lot_id) values(u,s,plan,date_trunc('month',now()),date_trunc('month',now())+interval '1 month',op,3,'reserved','refund-rollback-fixture-in-flight',lot);
 perform public.apply_ai_payment_adjustment(actor,'Verified fixture provider evidence',evidence);
 if (select frozen from public.ai_payment_credit_lots where id=lot) is not true then raise exception 'Dispute did not freeze credits'; end if;
 blocked:=false;begin insert into public.ai_credit_ledger(user_id,subscription_id,plan_key,period_start,period_end,operation_key,credits,status,idempotency_key,payment_credit_lot_id) values(u,s,plan,date_trunc('month',now()),date_trunc('month',now())+interval '1 month',op,1,'reserved','refund-rollback-fixture-blocked',lot);exception when others then blocked:=true;end;
 if not blocked then raise exception 'Frozen credits were reserved'; end if;
 blocked:=false;begin update public.ai_credit_ledger set status='consumed' where user_id=u and idempotency_key='refund-rollback-fixture-in-flight';exception when others then blocked:=true;end;
 if not blocked then raise exception 'In-flight reservation consumed after dispute freeze'; end if;
 update public.ai_credit_ledger set status='released' where user_id=u and idempotency_key='refund-rollback-fixture-in-flight';
 results:=results||'[{"name":"freeze-before-consumption blocks settlement and permits release","status":"pass"}]';
 results:=results||'[{"name":"open dispute freezes new usage","status":"pass"}]';
 perform public.apply_ai_payment_adjustment(actor,'Verified fixture provider evidence',evidence||'{"action":"dispute_won"}');
 if (select frozen or revoked from public.ai_payment_credit_lots where id=lot) then raise exception 'Won dispute did not restore credit availability'; end if;
 perform public.apply_ai_payment_adjustment(actor,'Verified fixture provider evidence',evidence);
 if (select frozen from public.ai_payment_credit_lots where id=lot) then raise exception 'Stale open event refroze won dispute'; end if;
 results:=results||'[{"name":"won dispute and stale event handling","status":"pass"}]';
 perform public.apply_ai_payment_adjustment(actor,'Verified fixture provider evidence',evidence||'{"provider_object_id":"dispute:rollbackfixture2"}');
 perform public.apply_ai_payment_adjustment(actor,'Verified fixture provider evidence',evidence||'{"action":"dispute_lost","provider_object_id":"dispute:rollbackfixture2"}');
 if (select revoked from public.ai_payment_credit_lots where id=lot) is not true then raise exception 'Lost dispute did not revoke'; end if;
 blocked:=false;begin perform public.apply_ai_payment_adjustment(actor,'Verified fixture provider evidence',evidence||'{"action":"dispute_won","provider_object_id":"dispute:rollbackfixture2"}');exception when others then blocked:=true;end;
 if not blocked then raise exception 'Conflicting final dispute outcome accepted'; end if;
 results:=results||'[{"name":"lost dispute is permanent and conflicting outcome rejected","status":"pass"}]';
 perform public.apply_ai_payment_adjustment(actor,'Verified fixture provider evidence',evidence||'{"action":"refund","provider_object_id":"refund:rollbackfixture2","amount_minor":700}');
 if (select revoked from public.ai_payment_credit_lots where id=lot) is not true or (select credits from public.ai_credit_ledger where idempotency_key='refund-rollback-fixture-usage' and user_id=u)<>2 then raise exception 'Full refund or historical usage incorrect'; end if;
 if has_function_privilege('authenticated','public.apply_ai_payment_adjustment(uuid,text,jsonb)','EXECUTE') then raise exception 'Customer can adjust own payment'; end if;
 results:=results||'[{"name":"cumulative full refund preserves usage and service-only boundary","status":"pass"}]';
 -- Independent full refund with no preceding lost dispute, plus an unrelated payment.
 s:=gen_random_uuid();
 insert into public.ai_agent_subscriptions(id,user_id,plan_key,billing_interval,status,currency,amount,current_period_start,current_period_end) values(s,u,plan,'monthly','active','USD',10,now(),now()+interval '1 month');
 insert into public.ai_subscription_payments(reference,subscription_id,provider_transaction_id,amount_minor,currency,paid_at,period_start,period_end) values('refund-rollback-full-only',s,'refund-rollback-full-tx',1000,'USD',now(),now(),now()+interval '1 month');
 if not public.ai_payment_access_allowed(s) then raise exception 'Verified unrelated payment lacks access'; end if;
 evidence:='{"action":"refund","provider_object_id":"refund:rollback-full-only","reference":"refund-rollback-full-only","transaction_id":"refund-rollback-full-tx","currency":"USD","amount_minor":1000,"verification_source":"provider_api"}';
 perform public.apply_ai_payment_adjustment(actor,'Verified fixture provider evidence',evidence);
 if public.ai_payment_access_allowed(s) or exists(select 1 from public.ai_payment_credit_lots where payment_reference='refund-rollback-full-only' and not revoked) then raise exception 'Full refund did not revoke all paid lots'; end if;
 blocked:=false;begin perform public.apply_ai_payment_adjustment(actor,'Verified fixture provider evidence',evidence||'{"provider_object_id":"refund:rollback-excess"}');exception when others then blocked:=true;end;
 if not blocked then raise exception 'Excess cumulative refund accepted'; end if;
 results:=results||'[{"name":"standalone full refund revokes only funded periods and prevents excess refunds","status":"pass"}]';
 return results;
end; $$;
select pg_temp.test_payment_adjustments() as results;
rollback;
